function Xon(r, u) {
  let d = [];
  for (let p = r; p <= u; p++) d.push(p);
  return d;
}
function W3(r) {
  let u = Won(r);
  return [u.toLowerCase(), u];
}
function NOe(r, u) {
  return Xon(r, u).map((d) => W3(d));
}
